function useSharedCounter(initial = 0) {
  const countRef = useRef(initial);
  const countState = useState(initial);

  const increment = useCallback(() => {
    countRef.current += 1;
    countState[1](countRef.current); // Re-render when needed
  }, []);

  return { count: countState[0], increment, countRef };
}

function useLogCount() {
  const { countRef } = useSharedCounter();

  useEffect(() => {
    console.log('Count changed:', countRef.current);
  }, [countRef.current]);

  return countRef.current;
}

// In component
function Counter() {
  const { count, increment } = useSharedCounter();
  const loggedCount = useLogCount();

  return (
    <button onClick={increment}>
      Count: {count} (logged: {loggedCount})
    </button>
  );
}

type Theme = 'light' | 'dark' | 'system';

interface ThemeContextValue {
  theme: Theme;
  setTheme: (theme: Theme) => void;
}

const ThemeContext = createContext<ThemeContextValue | undefined>(undefined);

function useTheme() {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
}

function useThemedClassName(baseClass: string) {
  const { theme } = useTheme();
  return `${baseClass}--${theme}`;
}

function useThemedColor(light: string, dark: string) {
  const { theme } = useTheme();
  return theme === 'dark' ? dark : light;
}

// Both hooks share the same theme state via context
function Button() {
  const className = useThemedClassName('btn');
  const bgColor = useThemedColor('#ffffff', '#1a1a1a');
  return <button className={className} style={{ backgroundColor: bgColor }}>Click</button>;
}

type Listener = () => void;

class Store<T> {
  private state: T;
  private listeners = new Set<Listener>();

  constructor(initial: T) {
    this.state = initial;
  }

  getState() {
    return this.state;
  }

  setState(partial: Partial<T> | ((prev: T) => T)) {
    this.state = { ...this.state, ...(typeof partial === 'function' ? partial(this.state) : partial) };
    this.listeners.forEach(l => l());
  }

  subscribe(listener: Listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }
}

const userStore = new Store({ name: '', loggedIn: false });

function useUserStore() {
  return useSyncExternalStore(
    userStore.subscribe.bind(userStore),
    userStore.getState.bind(userStore)
  );
}

function useUserName() {
  const user = useUserStore();
  return user.name;
}

function useLoginStatus() {
  const user = useUserStore();
  return user.loggedIn;
}

// Both hooks read from the same external store
function Profile() {
  const name = useUserName();
  const loggedIn = useLoginStatus();
  return <div>{loggedIn ? `Hello, ${name}` : 'Please log in'}</div>;
}

// React Component Example with Hooks
import React, { useState, useEffect, useCallback } from 'react';

function DataFetcher({ endpoint }) {
  // State management with useState
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // useCallback for memoized fetch function
  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(endpoint);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const result = await response.json();
      setData(result);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [endpoint]);

  // useEffect for side effects
  useEffect(() => {
    fetchData();
  }, [fetchData]);

  if (loading) return <div className="loading">Loading...</div>;
  if (error) return <div className="error">Error: {error}</div>;

  return (
    <div className="data-container">
      <h2>Fetched Data</h2>
      <pre>{JSON.stringify(data, null, 2)}</pre>
    </div>
  );
}

export default DataFetcher;
